# File: simulator.py import random from models import ArticoloMagazzino, RisultatoAnalisiScorte class SimulatoreTriennale:    """Simula la gestione delle scorte su 3 anni di esercizio (1.095 giorni)."""    def __init__(self, articolo: ArticoloMagazzino, serie_giornaliera: list[float],                 penale_stockout_unitaria: float = 15.0):        self.articolo = articolo        self.serie_giornaliera = serie_giornaliera        self.penale_stockout_unitaria = penale_stockout_unitaria    @staticmethod    def genera_serie_triennale(media_g: float, dev_std_g: float,                               ampiezza_stagionale: float = 0.15, seed: int = 42) > list[float]:        """Genera 1.095 giorni (3 anni) di domanda sintetica con componente stagionale."""        rng = random.Random(seed)        serie = []        for giorno in range(1095):            fattore_stag = 1.0 + ampiezza_stagionale * (                1.0 if 150 <= (giorno % 365) <= 240 else -0.4            )            domanda = max(0.0, rng.gauss(media_g * fattore_stag, dev_std_g))            serie.append(round(domanda, 2))        return serie    def simula_politica(self, q_ordine: float, rop: float, seed: int = 100) -> dict:        """Esegue la simulazione giornaliera sui 3 anni restituendo i KPI operativi."""        rng = random.Random(seed)        giacenza_fisica = rop + (q_ordine / 2.0)        ordini_in_transito = []  # lista di tuple (giorno_arrivo, quantita)        ordini_emessi = 0        unita_stockout = 0.0        giorni_stockout = 0        somma_giacenze = 0.0        for giorno, domanda in enumerate(self.serie_giornaliera):            # 1. Ricezione ordini previsti per la giornata odierna            arrivi_oggi = [q for (g_arr, q) in ordini_in_transito if g_arr == giorno]            if arrivi_oggi:                giacenza_fisica += sum(arrivi_oggi)                ordini_in_transito = [(g, q) for (g, q) in ordini_in_transito if g != giorno]            # 2. Soddisfacimento della domanda giornaliera            if giacenza_fisica >= domanda:                giacenza_fisica -= domanda            else:                unita_stockout += (domanda - giacenza_fisica)                giacenza_fisica = 0.0                giorni_stockout += 1